import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    n = len(coords)

    adj: list[list[list[int]]] = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    INF = 10**18
    pot = [INF] * n
    pot[0] = 0
    for u in range(n):
        if pot[u] == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pot[u] + cost < pot[v]:
                pot[v] = pot[u] + cost

    total_cost = 0
    remaining = k
    sink = n - 1

    while remaining > 0:
        dist = [INF] * n
        dist[0] = 0
        parent_node = [-1] * n
        parent_edge = [-1] * n
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_node[v] = u
                        parent_edge[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(n):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[sink] >= 0:
            break

        push = remaining
        v = sink
        while v != 0:
            u = parent_node[v]
            ei = parent_edge[v]
            if adj[u][ei][1] < push:
                push = adj[u][ei][1]
            v = u

        v = sink
        while v != 0:
            u = parent_node[v]
            ei = parent_edge[v]
            rev = adj[u][ei][3]
            adj[u][ei][1] -= push
            adj[v][rev][1] += push
            v = u

        remaining -= push
        total_cost += push * pot[sink]

    return -total_cost
